H('98.d.21.H',3,"A quantity takeoff for a 12-foot by 10-foot deck floor needs how many square feet of decking?","120",["22","44","240"],"12 x 10 = 120.")
H('98.d.21.H',4,"After figuring the decking area, adding about 10 percent more material allows for:","Waste from cuts",["Rain","Weight","Tips"],"Waste factor is standard.")
H('98.d.22.A',3,"Platform framing is a system in which each floor:","Is built as a platform on top of the walls below",["Is built in the foundation only","Has no joists","Floats"],"Platform framing is most common.")
H('98.d.22.A',4,"A framing system where wall studs run from foundation to roof is called:","Balloon framing",["Platform framing","Pole barn","Timber peg"],"Balloon framing uses long studs.")
H('98.d.22.B',3,"A floor system's drawings and specs show joist size and:","Spacing",["Color","Age","Brand of paint"],"Spacing affects strength.")
H('98.d.22.B',4,"To determine the required joist size, a carpenter refers to the:","Span tables or engineered plans",["Weather map","Calendar","Phone list"],"Span tables give allowed sizes.")
H('98.d.22.C',3,"The member that sits on the foundation and supports floor joists is the:","Sill plate",["Rafter","Ridge","Soffit"],"Sills anchor the floor system.")
H('98.d.22.C',4,"The framing member that closes the ends of floor joists is the:","Rim joist (band joist)",["Ridge board","Header","Purlin"],"Rim joists cap the ends.")
H('98.d.22.D',3,"Sills are fastened to the foundation with:","Anchor bolts",["Tape","Rope","Wood glue only"],"Bolts prevent uplift.")
H('98.d.22.D',4,"A sill sealer is placed under the sill plate to:","Block air and moisture",["Add weight","Hide nails","Add color"],"Sealing improves performance.")
H('98.d.22.E',3,"A girder in a floor system:","Supports the joists along a main line",["Covers the roof","Is a type of siding","Hangs the door"],"Girders carry joist loads.")
H('98.d.22.E',4,"A longer girder span usually calls for a member that is:","Larger",["Smaller","Thinner","Identical"],"Longer spans need stronger members.")
H('98.d.22.F',3,"Bridging between joists helps to:","Stiffen the floor and share loads",["Add noise","Weaken the floor","Lower cost only"],"Bridging resists twisting.")
H('98.d.22.F',4,"X-bridging is made of two pieces that:","Cross diagonally between adjacent joists",["Run parallel","Hang vertically","Lie flat"],"X patterns brace joists.")
H('98.d.22.G',3,"Common finish flooring materials include:","Hardwood, tile, and carpet",["Mud and straw","Tissue paper","Fishing line"],"Finishes vary by use.")
H('98.d.22.G',4,"Laminate flooring is often installed as a:","Floating floor",["Glued-down hardwood","Nailed slab","Tile mosaic"],"Floating floors snap together.")
H('98.d.22.H',3,"Subflooring is the layer that:","Is nailed to the joists and supports finish flooring",["Hangs from ceilings","Covers shingles","Is siding"],"Subfloors give a working surface.")
H('98.d.22.H',4,"Underlayment is installed to:","Provide a smooth base for finish flooring",["Make noise","Cover pipes","Hold nails"],"It smooths and cushions.")
H('98.d.22.I',3,"Subfloor panels are commonly fastened with:","Ring-shank nails or screws and adhesive",["Staples only","Tape","Paper clips"],"Ringshanks resist withdrawal.")
H('98.d.22.I',4,"Using fasteners that are too short in a subfloor can cause:","Loose panels and squeaks",["Stronger floors","Quiet floors","Warm floors"],"Fastener length matters.")
H('98.d.22.J',3,"A floor is 16 feet long and joists are 16 inches on center. About how many joists are needed (add one)?","13",["16","9","25"],"192 / 16 = 12 spaces; 13 joists.")
H('98.d.22.J',4,"Four-by-eight panels cover 32 square feet. A 12 by 16 floor needs how many panels (no waste)?","6",["4","8","12"],"192 / 32 = 6.")
H('98.d.22.K',3,"When constructing a floor assembly, the first member laid out is typically the:","Sill plate",["Finish floor","Door","Window"],"Start at the bottom.")
H('98.d.22.K',4,"Check a completed floor frame for squareness by comparing:","The two diagonals",["Paint colors","Board brands","Weather"],"Equal diagonals mean square.")
H('98.d.23.A',3,"A wall layout shows the location of studs, openings, and:","Plates and corners",["Menus","Light bulbs only","Paint"],"Layout marks all framing.")
H('98.d.23.A',4,"Ceiling layout marks locate the position of:","Joists and fixtures",["Doorknobs","Furniture","Appliances"],"Ceiling joists need layout.")
H('98.d.23.B',3,"A wood-frame wall is laid out on the:","Top and bottom plates",["Roof","Footings","Rafters"],"Plates carry the marks.")
H('98.d.23.B',4,"A king stud and trimmer stud are used at a window opening to:","Support the header",["Hold paint","Hide wires","Cover siding"],"Trimmers carry the header.")
H('98.d.23.C',3,"Before raising an assembled exterior wall, the carpenter should have:","Bracing ready to hold it plumb",["Nothing","A ladder only","Paint"],"Braces hold walls upright.")
H('98.d.23.C',4,"The exterior wall assembly is nailed together while it lies:","Flat on the subfloor",["In the air","On the roof","In a truck"],"Walls are framed flat then raised.")
H('98.d.23.D',3,"Wall sheathing is installed to:","Add rigidity and a base for siding",["Provide light","Hold paint","Cool air"],"Sheathing stiffens the wall.")
H('98.d.23.D',4,"Common sheathing materials include:","Plywood and OSB",["Cardboard","Carpet","Foam peanuts"],"Panels are most common.")
H('98.d.23.E',3,"After tilting an exterior wall into place, it is temporarily held with:","Diagonal braces",["Tape","Paper","Loose nails only"],"Braces hold plumb until sheathed.")
H('98.d.23.E',4,"Holding a long level against an erected wall confirms the wall is vertical, or:","Plumb",["Painted","Insulated","Dry"],"Verticality is required.")
H('98.d.23.F',3,"When wood framing is used inside masonry walls, it is called:","Furring",["Shingling","Soffiting","Pouring"],"Furring strips attach finishes.")
H('98.d.23.F',4,"Wood framing that sits against concrete or masonry should be:","Pressure-treated or protected from moisture",["Untreated","Painted only","Left bare"],"Moisture rots untreated wood.")
H('98.d.23.G',3,"Metal studs are often used in commercial buildings because they are:","Non-combustible and uniform",["Flammable","Rot prone","Irregular"],"Steel resists fire and rot.")
H('98.d.23.G',4,"Metal studs are fastened to track with:","Screws",["Tape","Wood glue","Staples"],"Screws or crimps connect steel.")
H('98.d.23.H',3,"Ceiling joists tie the walls together and support:","Ceiling finish and, often, insulation",["The foundation","The sidewalk","The siding"],"They carry ceilings and ties.")
H('98.d.23.H',4,"When cutting ceiling joists, they should be notched only:","According to code limits",["Anywhere","Through the middle","Randomly"],"Over-notching weakens joists.")
H('98.d.23.I',3,"Studs at 16 inches on center on a 24-foot wall need about how many studs (add one)?","19",["24","12","30"],"288 / 16 = 18; plus 1 = 19.")
H('98.d.23.I',4,"Estimating framing materials should include extra for:","Corners, openings, and waste",["Nothing","Paint","Furniture"],"Extras add studs.")
H('98.d.24.A',3,"The 'run' of a roof is the:","Horizontal distance from the wall to the center line",["Vertical height","Slope length","Overhang width"],"Run is horizontal.")
H('98.d.24.A',4,"A roof that rises 6 inches for every 12 inches of run has a pitch of:","6 in 12",["12 in 6","3 in 12","1 in 6"],"Pitch is rise over run.")
H('98.d.24.B',3,"A gable roof has two sloping planes that meet at the:","Ridge",["Footing","Sill","Header"],"The ridge is the peak.")
H('98.d.24.B',4,"A hip roof differs from a gable roof because it:","Slopes on all four sides",["Has no rafters","Is flat","Has only a ridge"],"Hip roofs slope to each wall.")
H('98.d.24.C',3,"Rafter length can be found with a:","Framing square rafter table or the Pythagorean theorem",["Compass","Mallet","Clamp"],"Both methods work.")
H('98.d.24.C',4,"A roof has 12 feet of run and 5 feet of rise. The rafter length (before overhang) is about:","13 feet",["17 feet","7 feet","15 feet"],"sqrt(144+25)=13.")
H('98.d.24.D',3,"Trusses are prefabricated frames that:","Span the width of the building and support the roof",["Hold the siding","Replace windows","Cover floors"],"Trusses are engineered.")
H('98.d.24.D',4,"A common type of truss has webs forming:","Triangles",["Circles","Squares","Spirals"],"Triangles are rigid.")
H('98.d.24.E',3,"A speed square can be used to mark:","Rafter angles",["Colors","Wire","Pipe"],"Speed squares have pitch scales.")
H('98.d.24.E',4,"The 'plumb cut' on a rafter is the cut that sits:","Vertical at the ridge",["Horizontal on the floor","In the foundation","Under the sill"],"Plumb cut meets the ridge board.")
H('98.d.24.F',3,"Roof sheathing is typically:","Plywood or OSB panels",["Foam only","Carpet","Glass"],"Panels cover rafters.")
H('98.d.24.F',4,"Plywood clips (H-clips) between roof panels are used to:","Support the panel edges",["Hold paint","Cut panels","Hide nails"],"Clips prevent edge sag.")
H('98.d.24.G',3,"Gable end vents are installed to:","Let attic air circulate",["Block air","Add weight","Hold paint"],"Ventilation reduces moisture.")
H('98.d.24.G',4,"Without attic ventilation, hot summer air can:","Damage shingles and raise cooling costs",["Cool shingles","Lower bills","Reduce moisture"],"Ventilation protects the roof.")
H('98.d.24.H',3,"When setting trusses, the first truss is braced:","To stay plumb and in position",["Loosely","Upside down","Without nails"],"Bracing prevents collapse.")
H('98.d.24.H',4,"Trusses are usually spaced:","24 inches on center",["8 feet","Randomly","1 inch"],"Common spacing for trusses.")
H('98.d.24.I',3,"A roof opening for a chimney is framed with:","Headers and trimmers",["Shingles","Sod","Paper"],"Headers frame openings.")
H('98.d.24.I',4,"Framing around a roof opening must keep:","Clearance from the chimney as required by code",["Zero clearance","The wood touching bricks","Nothing"],"Codes require clearances.")
H('98.d.24.J',3,"To estimate roof sheathing, you first find the:","Total roof area",["Sky color","Wall paint","Window count"],"Area drives panel count.")
H('98.d.24.J',4,"A roof 20 feet by 30 feet in plan with a pitch factor of 1.12 has about how much surface area?","672 square feet",["600 square feet","540 square feet","720 square feet"],"600 x 1.12 = 672.")
H('98.d.25.A',3,"A window that opens by sliding sideways is a:","Slider",["Casement","Awning","Fixed"],"Sliders move horizontally.")
H('98.d.25.A',4,"A window that is hinged on the side and cranks open is a:","Casement window",["Double-hung","Fixed window","Hopper"],"Casements swing outward.")
H('98.d.25.B',3,"The horizontal piece at the bottom of a window opening is the:","Sill",["Head","Jamb","Mullion"],"Sill sheds water.")
H('98.d.25.B',4,"The flashing around a window prevents:","Water leaks into the wall",["Noise","Dust","Glare"],"Flashing diverts water.")
H('98.d.25.C',3,"Proper window installation requires the unit to be:","Plumb, level, square, and flashed",["Crooked","Unsealed","Wet"],"Correct install prevents leaks.")
H('98.d.25.C',4,"Shims placed at hinge locations on a window help to:","Keep the frame from bowing",["Add weight","Hide holes","Change color"],"Shims support the frame.")
H('98.d.25.D',3,"A pre-hung window comes with:","The sash already in a frame",["Only glass","Only trim","Only a sill"],"Pre-hung simplifies installing.")
H('98.d.25.D',4,"A pre-hung window is secured to the opening through the:","Nailing fin or jamb with shims",["Glass","Paint","Screen"],"Fasteners go through the frame.")
H('98.d.25.E',3,"Exterior doors are commonly made of:","Steel, fiberglass, or wood",["Paper","Foam only","Cardboard"],"Durable materials are used.")
H('98.d.25.E',4,"A steel exterior door has a core of:","Insulating foam",["Water","Sand","Paper only"],"Foam improves R-value.")
H('98.d.25.F',3,"The vertical side members of a door frame are the:","Jambs",["Sills","Sashes","Mullions"],"Jambs surround the door.")
H('98.d.25.F',4,"The strip on the doorframe against which the door closes is the:","Door stop",["Threshold","Weatherstrip","Sill"],"Stops limit the swing.")
H('98.d.25.G',3,"A threshold at an exterior door helps to:","Seal the bottom of the opening",["Add height","Block air only","Hold paint"],"Thresholds reduce drafts.")
H('98.d.25.G',4,"An adjustable threshold lets installers:","Fine-tune the seal against the door bottom",["Change the door color","Lengthen the door","Make noise"],"Adjustment improves sealing.")
H('98.d.25.H',3,"Before installing a pre-hung exterior door, the carpenter should check that the sill is:","Level",["Rough","Bare","Wet"],"A level sill ensures square fit.")
H('98.d.25.H',4,"The door is secured to the framing through the jamb with:","Screws and shims",["Tape","Paper","Staples"],"Proper fastening keeps alignment.")
H('98.d.25.I',3,"A lockset that turns a bolt to secure the door is a:","Deadbolt",["Passage latch","Door stop","Hinge"],"Deadbolts add security.")
H('98.d.25.I',4,"The part of a lock that extends into the doorframe is the:","Bolt",["Strike","Knob","Escutcheon"],"The bolt engages the strike.")
H('98.d.25.J',3,"Installing a lockset begins with:","Drilling holes to the template",["Painting","Guessing","Cutting the jamb"],"Templates guide drilling.")
H('98.d.25.J',4,"The strike plate is installed on the:","Door jamb",["Door face","Hinge","Threshold"],"The strike receives the bolt.")
H('98.d.25.K',3,"A storm door is installed to:","Add protection and insulation to the entry",["Remove the main door","Lower security","Block daylight"],"Storm doors provide protection.")
H('98.d.25.K',4,"A garage overhead door is moved by:","Springs and tracks",["Rope only","Ice","Magnets only"],"Springs counterbalance weight.")
H('98.d.26.A',3,"A staircase with a landing and a turn is a:","L-shaped or U-shaped stair",["Straight run only","Spiral only","Ladder"],"Landings allow turns.")
H('98.d.26.A',4,"A stair that winds around a central post is a:","Spiral stair",["Straight stair","Winder","Box stair"],"Spiral stairs save space.")
H('98.d.26.B',3,"The vertical part of a step is the:","Riser",["Tread","Stringer","Nosing"],"The riser is the rise.")
H('98.d.26.B',4,"The horizontal part of a step is the:","Tread",["Riser","Baluster","Newel"],"You step on the tread.")
H('98.d.26.C',3,"Stringers are the angled supports that carry the:","Treads and risers",["Roof","Windows","Doors"],"Stringers hold steps.")
H('98.d.26.C',4,"Exterior stairs should use:","Pressure-treated or weather-resistant materials",["Paper","Cardboard","Foam"],"Weather exposure demands durable lumber.")
H('98.d.26.D',3,"On a stair drawing, the number of risers is usually:","Marked with an arrow and a count",["Left out","Hidden","Painted"],"Drawings show the count.")
H('98.d.26.D',4,"A stair detail shows dimensions for the:","Rise, run, and headroom",["Paint color","Light switch","Door color"],"Stair plans list critical numbers.")
H('98.d.26.E',3,"A total rise of 108 inches divided by a 7.5-inch riser gives about how many risers?","14",["18","10","8"],"108 / 7.5 = 14.4, so use 14.")
H('98.d.26.E',4,"If a stair has 14 risers and each tread is 10 inches, the total run (13 treads) is:","130 inches",["140 inches","100 inches","108 inches"],"13 x 10 = 130.")
H('98.d.29.A',3,"A team is a group of people who:","Work together toward a common goal",["Work alone","Compete only","Argue constantly"],"Teams share purpose.")
H('98.d.29.A',4,"A framing crew working in sequence shows that teams function best when members:","Communicate and depend on each other",["Ignore others","Work in secret","Block each other"],"Coordination drives success.")
H('98.d.29.B',3,"Using teamwork to solve a problem means:","Sharing ideas and combining strengths",["Working alone","Hiding ideas","Ignoring input"],"Many minds solve problems.")
H('98.d.29.B',4,"If a roof cut doesn't fit, a team solves it best by:","Discussing options and testing a fix together",["Blaming one worker","Ignoring it","Walking away"],"Collaboration leads to solutions.")
H('98.d.29.C',3,"A team leader typically:","Guides the team and keeps work on track",["Does nothing","Sleeps","Quits"],"Leaders organize.")
H('98.d.29.C',4,"A team member's role is to:","Complete assigned tasks and support the team",["Ignore tasks","Compete with leader","Skip meetings"],"Members contribute.")
H('98.d.29.D',3,"A characteristic of a good leader is:","Listening and being fair",["Being rude","Playing favorites","Hiding information"],"Good leaders respect others.")
H('98.d.29.D',4,"Leaders earn trust by:","Keeping promises and setting an example",["Breaking promises","Avoiding responsibility","Blaming others"],"Integrity matters.")
H('98.d.29.E',3,"Employers expect workers to arrive on time and:","Complete tasks reliably",["Take long breaks","Ignore safety","Skip training"],"Reliability is valued.")
H('98.d.29.E',4,"A good work habit in a shop is to:","Clean up your area at the end of the shift",["Leave tools out","Drop trash","Skip cleanup"],"Cleanup is part of the job.")
H('98.d.29.F',3,"Harassment in the workplace is:","Unwelcome behavior that creates a hostile environment",["Friendly teamwork","Normal feedback","A safety rule"],"Harassment is prohibited.")
H('98.d.29.F',4,"Discrimination means:","Treating people unfairly because of a protected trait",["Hiring the most skilled","Giving everyone the same tools","Following a schedule"],"It is illegal.")
H('98.d.29.G',3,"A time-management technique is to:","Make a daily task list and prioritize",["Wait until deadlines","Work without plan","Ignore due dates"],"Lists organize time.")
H('98.d.29.G',4,"Doing the most important task first, before minor ones, is called:","Prioritizing",["Procrastinating","Daydreaming","Skipping"],"Prioritizing maximizes results.")

# ---------------- 127.103 Masonry ----------------
H('103.d.1.A',3,"A concrete masonry unit (CMU) is commonly called a:","Concrete block",["Wood plank","Clay brick","Glass tile"],"CMUs are made of concrete.")
H('103.d.1.A',4,"Hollow CMUs are used in walls because they are:","Strong, lighter than solid units, and able to be filled with grout and rebar",["Soft and weak","Made of wood","Waterproof by nature"],"Cores allow reinforcement.")
H('103.d.1.B',3,"Bricks are made from:","Clay fired in a kiln",["Plastic","Wood chips","Paper"],"Fired clay hardens into brick.")
H('103.d.1.B',4,"Brick veneer on a house is mostly:","A decorative, weather-resistant outer layer",["The main load-bearing frame","The foundation","The roof"],"Veneer is attached to the structure.")
H('103.d.1.C',3,"Natural stone used in construction includes:","Granite and limestone",["Cardboard","Plastic","Steel"],"Stone is quarried.")
H('103.d.1.C',4,"Stone is valued as a building material for its:","Durability and appearance",["Low weight","Flexibility","Transparency"],"Stone lasts for centuries.")
H('103.d.1.D',3,"Mortar is used to:","Bond masonry units together",["Cut bricks","Paint walls","Level the ground"],"Mortar is the glue of masonry.")
H('103.d.1.D',4,"Grout differs from mortar because it is:","Thinner and poured into cores or cavities",["Dry powder","A tool","Sand only"],"Grout fills voids.")
H('103.d.1.E',3,"In a running bond, each course of masonry units is:","Offset from the one below by half a unit",["Stacked straight above","Rotated 90 degrees","Left empty"],"Staggering distributes loads.")
H('103.d.1.E',4,"A wall built with one unit thickness is called a:","Single-wythe wall",["Cavity foundation","Double-roof","Pier-only"],"A wythe is a single vertical layer.")
H('103.d.2.A',3,"Besides medical bills, an accident on a masonry site can cost a company:","Lost production and higher insurance",["More profit","Faster work","Free equipment"],"Direct and indirect costs add up.")
H('103.d.2.A',4,"Fewer jobsite accidents help a mason's employer to:","Lower insurance premiums",["Pay more fines","Lose workers","Raise accident rates"],"Safety saves money.")
H('103.d.2.B',3,"A common cause of accidents on a masonry job is:","Unsafe acts like rushing and skipping PPE",["Wearing PPE","Planning","Training"],"Human behavior causes most accidents.")
H('103.d.2.B',4,"Poor lighting and cluttered scaffolds are unsafe:","Conditions",["Habits","Holidays","Rewards"],"Conditions contribute to accidents.")
H('103.d.2.C',3,"A masonry worker should recognize hazards such as:","Falling bricks and blocks",["Colorful paint","Quiet tools","Clean walkways"],"Falling objects injure.")
H('103.d.2.C',4,"Silica dust from cutting block is a hazard because it can damage the:","Lungs",["Knees","Hair","Eyes only"],"Silica causes serious lung disease.")
H('103.d.2.D',3,"Good housekeeping on a masonry site includes:","Keeping debris and mortar droppings cleared from walkways",["Leaving tools in aisles","Stacking blocks in doors","Ignoring spills"],"Clear paths prevent trips.")
H('103.d.2.D',4,"Stacking block at the base of a ladder is a housekeeping:","Violation",["Practice","Habit","Strategy"],"Ladders need clear bases.")
H('103.d.2.E',3,"Wet mortar and concrete can burn skin because they are:","Caustic",["Cold","Sweet","Soft"],"Cement is highly alkaline.")
H('103.d.2.E',4,"If wet concrete gets on your skin, you should:","Wash it off promptly with clean water",["Wait until it dries","Rub it with a rag","Cover it"],"Prolonged contact causes burns.")
H('103.d.2.F',3,"Flammable liquids such as solvents should be stored in:","Approved safety containers",["Open pails","Plastic grocery bags","Soda bottles"],"Containers prevent fires.")
H('103.d.2.F',4,"Smoking near flammable liquids is:","A fire hazard and not allowed",["Safe","Required","Encouraged"],"Ignition sources are prohibited.")
H('103.d.3.A',3,"Protective lenses or face shields are worn to protect from:","Flying chips and splashes",["Cold air","Noise","Odors"],"Eye and face protection matter.")
H('103.d.3.A',4,"When grinding block, a face shield is worn in addition to:","Safety glasses",["Sunglasses","A cap","Earrings"],"Layered protection is best.")
H('103.d.3.B',3,"Earplugs or earmuffs are required when noise reaches:","85 decibels or more over time",["10 decibels","30 decibels","50 decibels"],"OSHA sets limits near 85-90 dBA.")
H('103.d.3.B',4,"Using a masonry saw without hearing protection can lead to:","Permanent hearing loss",["Better hearing","Louder voice","More energy"],"Noise damages hearing.")
H('103.d.3.C',3,"Gloves for masons should protect hands from:","Abrasion and caustic mortar",["Nothing","Cold drinks","Sweat only"],"Rubber and leather gloves help.")
H('103.d.3.C',4,"Wearing rubber gloves with long cuffs while handling wet mortar helps prevent:","Chemical burns",["Cold feet","Thirst","Sunburn"],"Cement burns skin.")
H('103.d.3.D',3,"A respirator is needed when cutting block to protect against:","Dust",["Cold","Heat","Noise"],"Respirators filter air.")
H('103.d.3.D',4,"A respirator must be:","Properly fitted and rated for the hazard",["Loose","Any style","Worn on the forehead"],"Fit testing is required.")
H('103.d.4.A',3,"Fall protection is required on masonry scaffolds above:","The OSHA trigger height",["The ground","Zero feet","One inch"],"Fall protection triggers at set heights.")
H('103.d.4.A',4,"Guardrails, safety nets, or personal fall arrest are all methods of:","Fall protection",["Wind protection","Rain protection","Sun protection"],"Several systems protect from falls.")
H('103.d.4.B',3,"A personal fall arrest system includes an anchor, a connector, and a:","Full-body harness",["Belt only","Rope only","Hard hat only"],"Harness spreads forces.")
H('103.d.4.B',4,"A harness must be inspected before each use for:","Cuts, burns, and damage",["Color","Brand","Price"],"Damaged gear may fail.")
H('103.d.4.C',3,"A safe scaffold must be erected on:","Firm, level footing",["Soft mud","Loose bricks","Stacks of blocks"],"Solid base prevents collapse.")
H('103.d.4.C',4,"Before use, a scaffold should be inspected by a:","Competent person",["Passerby","New hire only","Neighbor"],"Competent person inspects scaffolds.")
H('103.d.4.D',3,"Toeboards or debris nets on scaffolds protect people below from:","Falling objects",["Rain","Heat","Noise"],"Overhead protection saves lives.")
H('103.d.4.D',4,"Workers below an overhead masonry operation should:","Be kept out of the drop zone or protected",["Stand directly under","Work faster","Ignore signs"],"Drop zones are barricaded.")
H('103.d.5.A',3,"A hand tool with a damaged handle should be:","Repaired or replaced before use",["Used","Painted","Sold"],"Damaged tools cause injuries.")
H('103.d.5.A',4,"Chisels should be used with a mushroomed head:","Never; dress or replace the head",["Always","Only outdoors","Only on brick"],"Mushroomed heads chip.")
H('103.d.5.B',3,"A masonry saw is safest to use when it:","Has a wet-cutting dust control and a guard",["Has no guard","Is dry","Is unplugged"],"Wet cutting reduces dust.")
H('103.d.5.B',4,"Before using a masonry saw, you should confirm the blade is:","Rated for masonry and free of cracks",["Dull","Cracked","Wooden"],"Inspect the blade.")
H('103.d.5.C',3,"A mortar mixer's moving paddles are dangerous because they can:","Catch hands or tools",["Cool mortar","Add water","Cut sand"],"Never reach into a running mixer.")
H('103.d.5.C',4,"Before cleaning a mortar mixer, you should:","Shut it off and lock out the power",["Leave it running","Use a shovel while running","Reach in"],"Lockout/tagout applies.")
H('103.d.5.D',3,"A handheld grinder with a missing guard should be:","Taken out of service",["Used carefully","Used on masonry only","Used outdoors"],"Guards prevent injuries.")
H('103.d.5.D',4,"Sparks from a grinder can ignite:","Flammable materials nearby",["Water","Sand","Bricks"],"Keep flammables away.")
H('103.d.5.E',3,"Powder-actuated tools use a:","Powder-charged load to drive fasteners",["Water jet","Air only","Magnet"],"They act like a firearm.")
H('103.d.5.E',4,"Only workers who have been trained and certified may use:","Powder-actuated tools",["Hammers","Tape measures","Levels"],"Training is required.")
H('103.d.5.F',3,"When working around a forklift, stay out of its:","Path and never walk under raised forks",["Rear mirror","Cab roof","Spare tire"],"Forklifts cause serious injuries.")
H('103.d.5.F',4,"A forklift operator must be:","Trained and certified",["Anyone available","Unlicensed","Distracted"],"Operator qualification is required.")
H('103.d.5.G',3,"A basic electrical safety guideline on a masonry site is to use:","Ground-fault circuit interrupters (GFCIs)",["Frayed cords","Wet extension cords","Bare wires"],"GFCIs protect from shock.")
H('103.d.5.G',4,"Power lines overhead require workers to:","Keep scaffolds and equipment at a safe distance",["Touch them","Climb them","Ignore them"],"Maintain clearance.")
H('103.d.5.H',3,"Masonry units should be stockpiled on:","Firm, level ground",["Soft mud","Slopes","Stacked planks"],"Stability prevents shifting.")
H('103.d.5.H',4,"Cement bags should be stored:","Dry, off the ground, and covered",["In puddles","In rain","On wet floors"],"Moisture hardens cement.")
H('103.d.5.I',3,"Bricks are stacked safely in cubes that are no more than:","A safe height set by the employer and manufacturer",["As high as possible","A single tall pile","Unbalanced"],"Stack height is limited.")
H('103.d.5.I',4,"Loose bricks on a pallet should be:","Banded or strapped for stability",["Left loose","Thrown","Stacked unevenly"],"Banding prevents spills.")
H('103.d.6.A',3,"A brick trowel is used to:","Pick up and spread mortar",["Cut bricks","Measure","Level"],"The trowel is the mason's basic tool.")
H('103.d.6.A',4,"A pointing trowel is used to:","Finish and repair joints",["Cut stones","Drive nails","Mix mortar"],"Pointing refines joints.")
H('103.d.6.B',3,"A brick hammer has one flat face and a:","Chisel end",["Claw","Saw","Bit"],"It can strike and split bricks.")
H('103.d.6.B',4,"A brick set (wide chisel) is used to:","Cut bricks cleanly",["Spread mortar","Measure","Mix mortar"],"Sets split brick.")
H('103.d.6.C',3,"A jointer is used to:","Shape mortar joints",["Cut brick","Mix mortar","Set levels"],"It compresses and finishes joints.")
H('103.d.6.C',4,"A soft brush is used to:","Remove excess mortar and dust from the wall surface",["Cut brick","Level a wall","Mix mortar"],"Brushing cleans up joints.")
H('103.d.6.D',3,"A tool commonly used to hold the line in place at a corner is a:","Line block or pin",["Wrench","Saw","Trowel"],"Line blocks hold strings.")
H('103.d.6.D',4,"A mason's hawk is used to:","Hold a small supply of mortar",["Cut brick","Measure","Hammer"],"A hawk keeps mortar handy.")
H('103.d.7.A',3,"A modular spacing rule helps masons to:","Lay out courses and openings accurately",["Cut mortar","Mix grout","Weigh bricks"],"Rules give course heights.")
H('103.d.7.A',4,"On a standard modular spacing rule, three courses of brick with mortar joints measure:","8 inches",["6 inches","12 inches","10 inches"],"Standard modular brick runs 2 2/3 inches per course, so three courses total 8 inches.")
H('103.d.7.B',3,"A mason uses a level to check that a course is:","Horizontal",["Painted","Vertical only","Diagonal"],"Levels indicate horizontal and vertical alignment.")
H('103.d.7.B',4,"Placing a level on its end against a wall's edge checks:","Plumb",["Color","Moisture","Weight"],"Vertical alignment.")
H('103.d.7.C',3,"A plumb bob is used to:","Find a true vertical line",["Cut stone","Mix mortar","Measure weight"],"Gravity gives vertical.")
H('103.d.7.C',4,"A laser level projects a:","Level or plumb reference line",["Smell","Sound","Heat"],"Lasers help alignment.")
H('103.d.7.D',3,"A corner pole is used to:","Guide course heights at wall ends",["Hold lunch","Support roofs","Cut stone"],"Poles set course marks.")
H('103.d.7.D',4,"A mason's line stretched between corners helps keep courses:","Straight and level",["Wavy","Uneven","Crooked"],"The line guides each unit.")

H('98.d.29.D',3,"On a framing crew, which trait best shows leadership?","Treating crew members respectfully and fairly",["Taking credit for others' work","Yelling when behind","Keeping plans secret"],"Respect builds a strong crew.")
H('98.d.29.D',4,"A crew lead who admits a measuring mistake and fixes it shows:","Honesty and accountability",["Weakness","Carelessness","Poor planning only"],"Owning errors earns trust.")
